/* The FACE plate's parse (base shape only; the specimen's feminine warp is a
 * live-face concern this static port does not carry). */
const parsePoly = (s: string) => s.split(' ').map(p => p.split(',').map(Number))
const PIX = FACE_DATA.pix.split(';').map(parsePoly)
const RAW_SIL = parsePoly(FACE_DATA.sil)
const SIL: [number, number][] = []
RAW_SIL.forEach((p, i) => {
  const q = RAW_SIL[(i + 1) % RAW_SIL.length]
  const n = Math.max(1, Math.ceil(Math.hypot(q[0] - p[0], q[1] - p[1]) / 12))
  for (let k = 0; k < n; k++) SIL.push([p[0] + (q[0] - p[0]) * k / n, p[1] + (q[1] - p[1]) * k / n])
})
const LM = {eyes: [[348, 437], [680, 437]], brow: [[350, 372], [678, 372]], nose: [516, 646], nostrils: [[481, 668], [551, 668]], mouth: [516, 751]} as const
const BOX = [166, 6, 700, 976] as const

const facePts = (poly: number[][]) => poly.map(p => p[0].toFixed(1) + ',' + p[1].toFixed(1)).join(' ')
const facePath = (polys: number[][][]) => polys.map(p => 'M' + p.map(q => q[0].toFixed(1) + ' ' + q[1].toFixed(1)).join('L') + 'Z').join('')

/* faceGeom at k=0 (the specimen's identity warp): polygons, centroids, landmarks. */
const GEOM = (() => {
  const cen = PIX.map(c => { let x = 0, y = 0; c.forEach(p => { x += p[0]; y += p[1] }); return [x / c.length, y / c.length] as [number, number] })
  return {
    pix: PIX, cen,
    lm: {eyes: LM.eyes, brow: LM.brow, nose: LM.nose, nostrils: LM.nostrils, mouth: LM.mouth, eye: 1, lip: 1, mw: 1, fem: 0},
    pts: PIX.map(facePts),
    silPath: 'M' + SIL.map(p => p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join('L') + 'Z',
    skinPath: facePath(PIX),
  }
})()

